// Adapter: decision-stamp  (Flow D, Decision)
//
// Rewrites the card in place so the chat history shows a settled record rather than three buttons
// that no longer do anything. Somebody scrolling back a month later should be able to read the
// outcome off the message that carried the decision.
//
// Node settings: JavaScript, Run Once for All Items.

const gate = $('Decision gate').first().json;
const card = $('Parse the button').first().json;
const settings = $('Settings D').first().json;

// The decision is written. What follows is optional: a covering note, and the only message in
// the workflow that reaches a counterparty. It is a link rather than an automatic send, because
// nothing should leave the building on a tap.
let base = String(settings.n8n_base_url || '');
while (base.endsWith('/')) base = base.slice(0, -1);
const noteUrl = `${base}/form/sample-decision?sample_id=${encodeURIComponent(gate.sample_id)}`;

const text = ST_VERDICT.decisionStamp
  ? ST_VERDICT.decisionStamp(gate)
  : `${gate.sample_id} - ${gate.update.decision} by ${gate.update.decision_by}.`;

return [
  {
    json: {
      chat_id: gate.chat_id || card.chat_id,
      message_id: gate.message_id || card.message_id,
      text: `${text}${String.fromCharCode(10)}${String.fromCharCode(10)}Add a note and notify the shipper:${String.fromCharCode(10)}${noteUrl}`,
    },
  },
];
